#include <queue>
#include <string>
#include <vector>

std::vector<std::string> serveAll(std::queue<std::string> line)
{
    std::vector<std::string> served{};
    while (!line.empty())
    {
        served.push_back(line.front());
        line.pop();
    }
    return served;
}

std::vector<int> largestFirst(const std::vector<int>& values)
{
    std::priority_queue<int> heap{};
    for (int value : values)
    {
        heap.push(value);
    }
    std::vector<int> result{};
    while (!heap.empty())
    {
        result.push_back(heap.top());
        heap.pop();
    }
    return result;
}
